"""Generated by AutoAir from the visual DAG spec 'v2_features'.

Do not edit by hand: changes are overwritten on the next deploy.
Edit the DAG in the AutoAir builder (spec: v2_features.autoair.json) instead."""

import datetime

from airflow.providers.smtp.notifications.smtp import SmtpNotifier
from airflow.providers.standard.operators.bash import BashOperator
from airflow.providers.standard.operators.empty import EmptyOperator
from airflow.sdk import (
    DAG,
    Asset,
    AssetAlias,
    AssetAny,
    AssetOrTimeSchedule,
    AsyncCallback,
    CronTriggerTimetable,
    DeadlineAlert,
    DeadlineReference,
    ExceptionRetryPolicy,
    Label,
    Param,
    RetryAction,
    RetryRule,
    task,
)

with DAG(
    dag_id="v2_features",
    description="Exercises AutoAir spec v2 features",
    schedule=AssetOrTimeSchedule(
        timetable=CronTriggerTimetable("0 3 * * *", timezone="Europe/Istanbul"),
        assets=AssetAny(Asset(name="orders", uri="s3://lake/orders"), AssetAlias("late_data")),
    ),
    start_date=datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc),
    catchup=False,
    tags=["autoair", "v2"],
    fail_fast=False,
    max_consecutive_failed_dag_runs=5,
    owner_links={"data": "mailto:data@example.com"},
    params={
        "region": Param(
            "eu",
            type="string",
            section="Target",
            enum=["eu", "us"],
            values_display={"eu": "Europe", "us": "United States"},
        ),
        "limit": Param(10, type="integer", minimum=1, maximum=1000),
        "run_date": Param("2026-01-01", type="string", format="date"),
    },
    on_failure_callback=[SmtpNotifier(to="oncall@example.com", subject="{{ dag.dag_id }} failed")],
    deadline=[
        DeadlineAlert(
            reference=DeadlineReference.DAGRUN_QUEUED_AT,
            interval=datetime.timedelta(seconds=7200),
            callback=AsyncCallback(SmtpNotifier, kwargs={"to": "oncall@example.com"}),
            name="finish_in_2h",
        )
    ],
    doc_md="## Notes\nOrders pipeline.",
) as dag:
    t_create_tmp = BashOperator(task_id="create_tmp", bash_command="mkdir -p /tmp/v2")

    @task.branch(task_id="choose")
    def choose(region):
        return "load_eu" if region == "eu" else "load_us"

    t_choose = choose(region="{{ params.region }}")
    t_load_eu = EmptyOperator(
        task_id="load_eu",
        retry_policy=ExceptionRetryPolicy(
            rules=[
                RetryRule(
                    exception="builtins.ConnectionError",
                    action=RetryAction.RETRY,
                    retry_delay=datetime.timedelta(seconds=30),
                ),
                RetryRule(exception="builtins.ValueError", action=RetryAction.FAIL),
            ]
        ),
        on_retry_callback=[SmtpNotifier(to="x@example.com")],
    )
    t_load_us = EmptyOperator(task_id="load_us")

    @task(task_id="pairs")
    def pairs():
        return [{"x": i, "y": i * 2} for i in range(3)]

    t_pairs = pairs()

    @task(
        task_id="add",
        trigger_rule="none_failed_min_one_success",
        map_index_template="{{ task.op_kwargs }}",
    )
    def add(x, y):
        return x + y

    t_add = add.partial().expand_kwargs(t_pairs)

    @task.short_circuit(task_id="is_ready")
    def is_ready():
        return True

    t_is_ready = is_ready()
    t_drop_tmp = BashOperator(task_id="drop_tmp", bash_command="rm -rf /tmp/v2")
    t_create_tmp.as_setup()
    t_drop_tmp.as_teardown(setups=[t_create_tmp])
    t_create_tmp >> [t_choose, t_drop_tmp]
    t_load_us >> t_pairs
    t_pairs >> t_add
    t_add >> t_is_ready
    t_is_ready >> t_drop_tmp
    t_load_eu >> t_pairs
    t_choose >> Label("eu") >> t_load_eu
    t_choose >> Label("us") >> t_load_us
